INSERT INTO daily_questions (bank_type, question_text, option_a, option_b, option_c, option_d, correct_answer, category) VALUES
('general', 'Toàn bộ công tác chấm công tại Công ty TNHH Doscom Holdings được thực hiện bằng hình thức nào?', 'Chấm công bằng vân tay đặt tại văn phòng.', 'Chấm công bằng định vị GPS qua ứng dụng Lark.', 'Chấm công bằng thẻ từ ra vào văn phòng.', 'Gửi email báo cáo ngày công cho quản lý trực tiếp hàng ngày.', 'B', 'Nội quy'),
('general', 'Công ty TNHH Doscom Holdings quy định thế nào về hình thức làm việc online tại nhà?', 'Áp dụng cho toàn bộ nhân viên khi có lý do cá nhân chính đáng.', 'Chỉ áp dụng đối với bộ phận Chăm sóc khách hàng và Kỹ thuật.', 'Công ty không áp dụng hình thức làm việc online tại nhà.', 'Cho phép nhân viên làm việc online 01 ngày/tuần.', 'C', 'Nội quy'),
('general', 'Khung giờ làm việc của ca hành chính từ Thứ 2 đến Thứ 7 hàng tuần được quy định như thế nào?', 'Từ 8h00 đến 17h00 hàng ngày (Thứ 7 về sớm 30 phút).', 'Từ 8h30 đến 17h30 hàng ngày (Thứ 7 về sớm 30 phút).', 'Từ 9h00 đến 18h00 hàng ngày (Thứ 7 về sớm 30 phút).', 'Từ 8h30 đến 18h00 hàng ngày (Thứ 7 về sớm 30 phút).', 'D', 'Nội quy'),
('general', 'Trong một ngày làm việc bình thường, cán bộ nhân viên phải thực hiện chấm công trên ứng dụng Lark bao nhiêu lần?', '01 lần duy nhất vào đầu giờ sáng khi đến công ty.', '02 lần: Check in khi đến và Check out khi về.', '04 lần: Check in/out đầu giờ và Check in/out giữa ca nghỉ.', 'Không bắt buộc số lần chấm công, chỉ cần quản lý xác nhận.', 'B', 'Nội quy'),
('general', 'Trường hợp không thể chấm công do lỗi phần mềm Lark hoặc các lý do khách quan khác, nhân viên cần phải làm gì?', 'Tự chấm công bù vào ngày làm việc tiếp theo.', 'Báo cáo bằng miệng cho Trưởng phòng/ban vào kỳ tính lương cuối tháng.', 'Báo ngay cho phòng Nhân sự để ghi nhận thời gian chấm công và khắc phục sự cố.', 'Chụp ảnh màn hình điện thoại tự lưu giữ và không cần báo ai.', 'C', 'Nội quy'),
('general', 'Trong một tháng, nhân viên được xin phép đi muộn/về sớm lý do cá nhân tối đa bao nhiêu lần?', 'Đi muộn tối đa 3 lần, về sớm tối đa 2 lần.', 'Đi muộn /về sớm tối đa 3 lần.', 'Đi muộn tối đa 5 lần, về sớm tối đa 5 lần.', 'Đi muộn tối đa /về sớm tối đa 5 lần.', 'D', 'Nội quy'),
('general', 'Quyền lợi ưu tiên về thời gian làm việc đối với lao động nữ nuôi con nhỏ dưới 12 tháng tuổi là gì?', 'Được nghỉ thêm 30 phút một ngày hưởng đủ lương.', 'Được nghỉ thêm 60 phút một ngày hưởng đủ lương (có thể chia ra sử dụng vào buổi trưa và buổi chiều) và phải báo với HCNS để theo dõi.', 'Được làm việc online tại nhà hoàn toàn cho đến khi con đủ 12 tháng tuổi.', 'Được về sớm trước 2 tiếng mỗi ngày và khấu trừ 10% lương cơ bản.', 'B', 'Quyền lợi'),
('general', 'Nếu nhân viên phải đi giải quyết công việc công ty bên ngoài trước giờ làm việc sáng hoặc về muộn không thể quay lại công ty, họ phải thực hiện thủ tục gì?', 'Nhắn tin xin phép đồng nghiệp chung nhóm check-in hộ trên Lark.', 'Làm phiếu phê duyệt "Out off office" trong mục phê duyệt trên Lark và được Trưởng phòng/ban phê duyệt.', 'Gọi điện thoại trực tiếp xin phép Giám đốc và không cần làm đơn từ.', 'Viết biên bản giấy giải trình nộp lại cho phòng Hành chính Nhân sự sau 3 ngày.', 'B', 'Nội quy'),
('general', 'Phiếu "Đơn xin đi muộn/về sớm" lý do cá nhân trường hợp về sớm phải được gửi phê duyệt trên Lark trước thời điểm về bao lâu?', 'Trước ít nhất 10 phút.', 'Trước ít nhất 15 phút.', 'Trước ít nhất 30 phút.', 'Trước ít nhất 1 tiếng.', 'B', 'Nội quy'),
('general', 'Phiếu "Đơn xin đi muộn/về sớm" lý do cá nhân trường hợp đi muộn phải được gửi phê duyệt trên Lark trước thời điểm nào?', 'Trước 8h30 cùng ngày.', 'Trước 7h00 cùng ngày.', 'Trước 22h00 của ngày hôm trước.', 'Trước 12h00 trưa cùng ngày.', 'B', 'Nội quy'),
('general', 'Khi muốn xin nghỉ phép từ 03 ngày trở lên, nhân viên phải gửi đơn xin nghỉ phép trước tối thiểu bao lâu?', 'Trước tối thiểu 03 ngày.', 'Trước tối thiểu 05 ngày.', 'Trước tối thiểu 01 tuần.', 'Trước tối thiểu 10 ngày.', 'C', 'Nội quy'),
('general', 'Trường hợp xin nghỉ phép 02 ngày, nhân viên phải nộp đơn xin nghỉ trên Lark trước tối thiểu bao lâu?', 'Trước tối thiểu 01 ngày.', 'Trước tối thiểu 02 ngày.', 'Trước tối thiểu 03 ngày.', 'Trước tối thiểu 05 ngày.', 'C', 'Nội quy'),
('general', 'Trường hợp xin nghỉ phép 01 ngày, nhân viên phải nộp đơn xin nghỉ trên Lark trước tối thiểu bao lâu?', 'Trước giờ bắt đầu làm việc ngày nghỉ 30 phút.', 'Trước tối thiểu 01 ngày.', 'Trước tối thiểu 02 ngày.', 'Phải nộp trước từ tuần trước', 'B', 'Nội quy'),
('general', 'Đối với trường hợp nghỉ đột xuất vì lý do bất khả kháng, nhân viên cần xử lý thế nào để chấm công hợp lệ?', 'Không cần thông báo, khi nào đi làm lại nộp đơn giải trình sau.', 'Thông báo ngay cho Trưởng bộ phận/người quản lý trực tiếp và HCNS để theo dõi chấm công, sau đó làm phiếu xin nghỉ bổ sung.', 'Nhắn tin cho đồng nghiệp cùng phòng nhờ chấm công hộ.', 'Gọi điện cho phòng Nhân sự xin phép và không cần làm phiếu trên Lark.', 'B', 'Nội quy'),
('general', 'Trường hợp nghỉ không xin phép hoặc không được phê duyệt nghỉ (Nghỉ không lý do) 1/2 ngày bị phạt như thế nào?', 'Phạt 2 điểm vi phạm quy chế.', 'Phạt 1 ngày lương.', 'Phạt 2 ngày lương.', 'Không tính lương buổi nghỉ đó và phạt cảnh cáo.', 'B', 'Kỷ luật'),
('general', 'Trường hợp nghỉ không xin phép hoặc không được phê duyệt nghỉ (Nghỉ không lý do) 01 ngày bị phạt thế nào?', 'Phạt trừ phép năm và phạt 1 ngày lương.', 'Phạt 2 ngày lương.', 'Phạt 3 ngày lương.', 'Đình chỉ công tác 03 ngày không hưởng lương.', 'B', 'Kỷ luật'),
('general', 'Mức xử phạt đối với hành vi đi muộn/ về sớm quá 5 lần trở lên, mỗi lần vi phạm phạt bao nhiêu điểm?', 'Phạt 0.5 điểm.', 'Phạt 1 điểm.', 'Phạt 1.5 điểm.', 'Phạt 2 điểm.', 'A', 'Kỷ luật'),
('general', 'Theo nguyên tắc sử dụng tài sản, hành vi nào sau đây cán bộ nhân viên KHÔNG được tự ý thực hiện?', 'Trao đổi, cho mượn, sử dụng chéo giữa các cá nhân/bộ phận', 'Di chuyển tài sản sang vị trí khác', 'Cả trao đổi/cho mượn tài sản lẫn di chuyển tài sản tùy tiện đều bị cấm', 'Cài đặt các phần mềm được phục vụ cho công việc cá nhân', 'C', 'Nội quy'),
('general', 'Mọi nhu cầu điều chuyển, sử dụng chung tài sản của Công ty phải được phê duyệt bởi cơ quan/cá nhân nào?', 'Do các cá nhân/bộ phận tự thỏa thuận và ký biên bản ghi nhớ', 'Phải được Phòng HCNS hoặc cấp quản lý trực tiếp phê duyệt', 'Phải được Chủ tịch Công ty phê duyệt bằng văn bản chính thức', 'Phải được Bộ phận Kế toán kiểm kê và đồng ý', 'B', 'Nội quy'),
('general', 'Số ngày phép hưởng nguyên lương tiêu chuẩn cho nhân viên chính thức là bao nhiêu ngày?', '0.5 ngày phép/tháng, tương đương 6 ngày phép/năm.', '01 ngày phép/tháng, tương đương 12 ngày phép/năm, thâm niên 5 năm + 01 ngày phép.', '1.5 ngày phép/tháng, tương đương 18 ngày phép/năm.', '02 ngày phép/tháng, tương đương 24 ngày phép/năm.', 'B', 'Quyền lợi'),
('general', 'Chế độ nghỉ phép hưởng nguyên lương của Công ty áp dụng cho đối tượng nhân sự nào?', 'Toàn bộ cán bộ nhân viên đang làm việc, kể cả nhân sự thử việc và cộng tác viên.', 'Áp dụng đối với tất cả nhân sự học việc, thực tập sinh có thời gian làm việc trên 1 tháng.', 'Chỉ áp dụng đối với nhân viên đã ký Hợp đồng lao động (làm việc chính thức) tại Công ty.', 'Chỉ áp dụng cho các nhân sự cấp quản lý từ cấp Trưởng phòng trở lên.', 'C', 'Quyền lợi'),
('general', 'Theo quy chế, nguyên tắc sử dụng ngày phép hằng tháng được quy định như thế nào?', 'Được cộng dồn tối đa 03 ngày phép sang các tháng tiếp theo trong cùng quý.', 'Ngày phép của tháng nào phải sử dụng hết tháng đó và không được tính cộng dồn vào các tháng tiếp theo.', 'Nhân viên có thể dồn toàn bộ 12 ngày phép để nghỉ một lần vào cuối năm.', 'Ngày phép chưa dùng hết sẽ được tự động quy đổi thành ngày nghỉ phép năm của năm tiếp theo.', 'B', 'Quyền lợi'),
('general', 'Trường hợp nhân viên tự ý nghỉ làm mà không làm đơn xin phép (trừ các tình huống bất khả kháng đã được thông báo và duyệt trước 7h00) thì sẽ bị xử lý như thế nào?', 'Tính vào ngày nghỉ phép không hưởng lương thông thường.', 'Tính là ngày nghỉ không lý do và bị xử lý kỷ luật theo quy định Nghỉ không lý do của Công ty.', 'Chỉ bị nhắc nhở nội bộ và trừ 0.5 điểm phạt vào lương.', 'Sẽ bị sa thải trực tiếp mà không cần tiến hành các bước xử lý kỷ luật.', 'B', 'Kỷ luật'),
('general', 'Tường hợp trễ deadline, cập nhật chậm tiến độ của Task sẽ chịu hình thức xử phạt là gì?', 'Trừ 1 điểm', 'Nhắc nhở lần 1 qua tin nhắn nội bộ.', 'Lập biên bản cảnh cáo trước toàn bộ phòng ban.', 'Hạ bậc xếp loại thi đua tháng.', 'A', 'Kỷ luật'),
('general', 'Ngày thành lập công ty TNHH Doscom Holdings là ngày bao nhiêu?', 'Ngày 1/6/2020', 'Ngày 2/6/2020', 'Ngày 1/6/2022', 'Ngày 2/6/2021', 'B', 'Văn hóa'),
('general', 'Theo quy định về cơ chế phạt, lỗi "Quên chấm công hằng ngày (check in/out)" ở lần thứ nhất bị trừ bao nhiêu điểm phạt?', 'Trừ 0.1 điểm phạt', 'Trừ 0.25 điểm phạt', 'Trừ 0.5 điểm phạt', 'Không trừ điểm, chỉ nhắc nhở qua Lark', 'B', 'Kỷ luật'),
('general', 'Từ lần thứ 2 trở đi, mức điểm phạt đối với lỗi "Quên chấm công hằng ngày (check in/out)" được tính toán lũy tiến theo nguyên tắc nào?', 'Cố định trừ 0.5 điểm cho mỗi lần quên chấm công tiếp theo', 'Điểm phạt bằng điểm phạt của lần 1 nhân đôi', 'Điểm phạt được tính bằng: Điểm phạt gần nhất + 0.25', 'Bị lập biên bản xử phạt trực tiếp trừ 1 ngày lương', 'C', 'Kỷ luật'),
('general', 'Hành vi "Làm việc riêng trong giờ làm, xem phim, chơi game,..." bị phát hiện sẽ bị trừ bao nhiêu điểm phạt vào lương?', 'Trừ 0.25 điểm phạt', 'Trừ 0.5 điểm phạt', 'Trừ 1 điểm phạt', 'Trừ 2 điểm phạt', 'B', 'Kỷ luật'),
('general', 'Lỗi "Không thực hiện đúng quy trình làm việc theo quy định" sẽ bị áp dụng chế tài xử phạt là bao nhiêu điểm phạt?', 'Trừ 0.5 điểm phạt', 'Trừ 1 điểm phạt', 'Trừ 2 điểm phạt', 'Trừ 3 điểm phạt', 'C', 'Kỷ luật'),
('general', 'Doscom quy định về điểm thưởng ra sao? Trường hợp nào nhân viên được cộng 0.5 điểm thưởng vào quỹ lương tuần?', 'Một tuần đi làm đầy đủ, đúng giờ (không đi muộn, về sớm)', 'Một tuần không mắc bất kỳ lỗi nào trong quy định', 'Cả hai trường hợp: đi đủ đúng giờ VÀ không mắc lỗi đều được cộng 0.5 điểm (mỗi trường hợp tính độc lập)', 'Đạt hiệu suất công việc xuất sắc nhất tuần', 'C', 'Lương thưởng'),
('general', 'Trong trường hợp ngày mùng 10 trùng vào ngày nghỉ hoặc ngày lễ theo quy định, lương của cán bộ nhân viên sẽ được chi trả vào thời điểm nào?', 'Sẽ được chi trả muộn hơn, vào ngày đầu tiên đi làm lại sau kỳ nghỉ.', 'Sẽ được chi trả vào ngày làm việc gần nhất trước hoặc sau ngày mùng 10 đó.', 'Mặc định chi trả đúng ngày mùng 10 thông qua hệ thống chuyển khoản tự động bất kể ngày lễ.', 'Sẽ được chuyển toàn bộ sang kỳ lương của tháng tiếp theo.', 'B', 'Lương thưởng'),
('general', 'Theo Thông báo số 2705/2025/TB-DC, cán bộ nhân viên cần phản hồi tin nhắn trong vòng bao lâu kể từ khi nhận được?', 'Trong vòng 15 phút.', 'Trong vòng 30 phút.', 'Trong vòng 45 phút.', 'Trong ngày làm việc.', 'B', 'Nội quy'),
('general', 'Nếu chưa thể trả lời chi tiết nội dung tin nhắn trong nhóm làm việc khi được tag tên, nhân viên cần xử lý như thế nào?', 'Bỏ qua tin nhắn và trả lời sau.', 'Chờ đến khi có đầy đủ thông tin chi tiết mới phản hồi.', 'Chỉ sử dụng emoji để kết thúc cuộc trò chuyện.', 'Gửi tin nhắn xác nhận tạm thời.', 'D', 'Nội quy'),
('general', 'Khi được tag tên trực tiếp (@tên) trong các nhóm làm việc, hành vi nào sau đây đúng quy định?', 'Không cần phản hồi nếu không liên quan trực tiếp đến nhiệm vụ của mình.', 'Chỉ cần thả biểu tượng cảm xúc (emoji) là đủ.', 'Phản hồi trong vòng 30 phút hoặc thông báo cụ thể thời điểm sẽ phản hồi.', 'Chờ đến khi kết thúc ngày làm việc mới phản hồi một thể.', 'C', 'Nội quy'),
('general', 'Tuyên ngôn văn hóa cải tiến chính thức của Doscom Holdings được quy định như thế nào?', '"Không ngừng sáng tạo, dẫn đầu công nghệ thông minh".', '"Cải tiến liên tục là chìa khóa của sự phát triển bền vững".', '"Mỗi ngày tại Doscom là một lần hệ thống, quy trình hoặc con người được cải tiến tốt hơn hôm qua.".', '"Chủ động tìm kiếm giải pháp và tối ưu hóa chi phí vận hành".', 'C', 'Văn hóa'),
('general', 'Theo Thông báo số 1508/2025/TB-DC, tần suất tổ chức học tập định kỳ của Phòng Kinh doanh và Phòng Marketing lần lượt là bao nhiêu?', 'Phòng Kinh doanh: 02 tuần/lần; Phòng Marketing: 01 tuần/lần.', 'Phòng Kinh doanh: 01 tuần/lần; Phòng Marketing: 01 tuần/lần.', 'Phòng Kinh doanh: 01 tuần/lần; Phòng Marketing: 02 tuần/lần.', 'Phòng Kinh doanh: 01 tháng/lần; Phòng Marketing: 02 tuần/lần.', 'C', 'Văn hóa'),
('general', 'Trưởng phòng các bộ phận áp dụng Văn hóa Học tập có nhiệm vụ gửi thông báo lịch học cụ thể lên nhóm làm việc trước tối thiểu bao nhiêu ngày?', 'Trước tối thiểu 01 ngày.', 'Trước tối thiểu 02 ngày.', 'Trước tối thiểu 03 ngày.', 'Trước tối thiểu 05 ngày.', 'C', 'Văn hóa'),
('general', 'Tầm nhìn chiến lược của Doscom Holdings đến năm 2030 định vị công ty phát triển trở thành gì?', 'Hệ sinh thái công nghệ hàng đầu Việt Nam chuyên bán lẻ thiết bị camera.', 'Hệ sinh thái công nghệ tiêu dùng và giải pháp an tâm hàng đầu Việt Nam, dẫn đầu bằng AI, mở rộng bền vững ra Đông Nam Á và các thị trường quốc tế chọn lọc.', 'Công ty gia công phần mềm xuất khẩu lớn nhất khu vực Đông Nam Á.', 'Tập đoàn phân phối thiết bị gia dụng thông minh lớn thứ hai tại Việt Nam.', 'B', 'Văn hóa'),
('general', 'Sứ mệnh của Doscom được xác định nhằm mang lại giá trị gì cho khách hàng?', 'Sự an tâm hằng ngày trong cuộc sống, công việc và di chuyển thông qua sản phẩm công nghệ đáng tin, dịch vụ có trách nhiệm và hệ thống vận hành tăng cường bởi AI.', 'Cam kết cung cấp các sản phẩm với mức giá rẻ nhất trên tất cả các sàn thương mại điện tử.', 'Giải pháp tài chính ngắn hạn kết hợp đầu tư bất động sản tích hợp.', 'Độc quyền phân phối phần cứng camera trên toàn lãnh thổ Đông Nam Á.', 'A', 'Văn hóa'),
('general', 'Giá trị cốt lõi số 01 ''Con người trên hết'' được Doscom xây dựng trên nền tảng cơ bản nào?', 'Doscom đặt sự tôn trọng, thấu hiểu và phát triển con người làm nền tảng trong mọi quyết định — từ khách hàng, nhân sự, đối tác đến cộng đồng.', 'Con người tại Doscom là công cụ tối ưu để tạo ra dòng tiền nhanh nhất.', 'Chỉ tập trung tối đa quyền lợi cho ban lãnh đạo, nhân viên cấp dưới tự chịu trách nhiệm phát triển cá nhân.', 'Luôn bỏ qua mọi quy trình kỷ luật để đảm bảo tinh thần thoải mái tối đa cho nhân viên.', 'A', 'Văn hóa'),
('general', 'Hành vi nào dưới đây là HÀNH VI ĐÚNG chuẩn mực của giá trị ''Con người trên hết''?', 'Góp ý thẳng nhưng tôn trọng; Đào tạo trước khi phán xét; Ghi nhận nỗ lực đúng và kết quả thật; Bảo vệ môi trường lành mạnh, rõ ràng, công bằng.', 'Nhận xét chung chung, hạn chế góp ý thẳng để tránh mâu thuẫn cá nhân.', 'Tập trung đánh giá kết quả cuối cùng của nhân viên mà không cần ghi nhận nỗ lực quá trình.', 'Ưu ái và trao cơ hội thăng tiến cho người thân thiết mà không cần đánh giá năng lực thực tế.', 'A', 'Văn hóa'),
('general', 'Tư duy cốt lõi của giá trị ''Khách hàng an tâm'' (Giá trị cốt lõi số 02) được định nghĩa là gì?', 'Khách hàng luôn đúng trong mọi hoàn cảnh, kể cả khi họ yêu cầu vi phạm pháp luật.', 'Không có khách hàng an tâm, Doscom không có giá trị thật.', 'Phải chốt đơn thật nhanh trước khi khách hàng kịp thay đổi ý định.', 'Chỉ phục vụ tận tình những khách hàng mua các sản phẩm có giá trị cao nhất.', 'B', 'Văn hóa'),
('general', 'Hành vi nào dưới đây bị nghiêm cấm và xếp vào nhóm HÀNH VI SAI của giá trị ''Khách hàng an tâm''?', 'Tư vấn đúng nhu cầu thật của khách hàng, nói rõ điểm mạnh và giới hạn của sản phẩm.', 'Bán bằng mọi giá; Hứa quá khả năng sản phẩm; Che giấu rủi ro sản phẩm; Đổ lỗi cho khách hàng; Chậm phản hồi bảo hành.', 'Theo dõi sát sao trải nghiệm sau mua của khách để cải tiến sản phẩm.', 'Bảo vệ niềm tin của khách hàng như tài sản quý giá nhất của thương hiệu.', 'B', 'Văn hóa'),
('general', 'Hành vi nào dưới đây là HÀNH VI SAI đối với giá trị ''Chính trực và minh bạch''?', 'Báo cáo đúng số liệu, chủ động báo lỗi, nói rõ rủi ro trước khi ra quyết định.', 'Không hứa điều công ty không chắc làm được; không che giấu phản hồi tiêu cực.', 'Sửa số liệu báo cáo; Che lỗi sản phẩm; Nói dối khách hàng; Hứa sai để chốt đơn; Đổ lỗi cho phòng ban khác; Im lặng khi thấy rủi ro; Báo cáo một nửa sự thật.', 'Truy nguyên nguyên nhân gốc thay vì đi tìm người để đổ lỗi.', 'C', 'Văn hóa'),
('general', 'Tư duy cốt lõi của giá trị ''Tốc độ có kỷ luật'' khẳng định điều gì về mối quan hệ giữa tốc độ và hệ thống?', 'Muốn nhanh thì phải chấp nhận bỏ bớt các bước kiểm soát hệ thống.', 'Nhanh không phải là bỏ bước. Nhanh là có hệ thống tốt hơn.', 'Hệ thống càng phức tạp thì tốc độ vận hành của doanh nghiệp càng cao.', 'Kỷ luật luôn là rào cản kìm hãm tốc độ phát triển sáng tạo.', 'B', 'Văn hóa'),
('general', 'Sự khác biệt căn bản nhất giữa ''Giá trị cốt lõi'' và ''Văn hóa hành vi'' tại Doscom Holdings là gì?', 'Giá trị cốt lõi do Nhà nước quy định; Văn hoá hành vi do công ty tự đặt ra.', 'Giá trị cốt lõi là chuẩn mực không thoả hiệp (vi phạm bị xử lý ngay); Văn hoá hành vi là chuẩn mực thực thi hằng ngày (ảnh hưởng đến đánh giá hiệu suất, thăng tiến, lương thưởng).', 'Giá trị cốt lõi áp dụng cho văn phòng Hà Nội; Văn hoá hành vi áp dụng cho các chi nhánh miền Nam.', 'Không có sự khác biệt nào, hai khái niệm này hoàn toàn trùng khớp về cả định nghĩa lẫn cách thực thi.', 'B', 'Văn hóa'),
('general', 'Theo tinh thần ''Trách nhiệm và không đổ lỗi'' (Tiêu chuẩn số 05), khi một dự án thất bại, người Doscom phải ứng xử thế nào?', 'Có lỗi thì báo, có vấn đề thì xử lý, có thất bại thì rút bài học, không biến người khác thành lý do cho sự thiếu trách nhiệm của mình.', 'Đổ trách nhiệm cho các yếu tố bất khả kháng từ môi trường kinh doanh bên ngoài.', 'Nhanh chóng tìm kiếm sai sót của các bộ phận phối hợp để giảm nhẹ khuyết điểm của mình.', 'Giữ kín thông tin thất bại để tránh ảnh hưởng đến bầu không khí thi đua chung.', 'A', 'Văn hóa'),
('general', 'Khẩu hiệu chính (Slogan) mang tính định hướng tối cao của Doscom Holdings là gì?', 'Công nghệ tin cậy, cuộc sống an tâm hằng ngày.', 'Tạo giá trị thật — Dẫn đầu bằng AI — Phụng sự bằng trách nhiệm.', 'Nói thật, làm thật, đo thật — Thành công bền vững.', 'Phát triển vì con người, cải tiến không ngừng nghỉ.', 'B', 'Văn hóa'),
('general', 'Công ty TNHH Doscom Holdings có bao nhiêu chi nhánh?', '1 chi nhánh ở HN', '2 chi nhánh ở HN', '1 chi nhánh ở HCM', '1 chi nhánh ở HN và 1 chi nhánh ở HCM', 'D', 'Văn hóa'),
('general', 'Đâu không phải là văn hóa đang tồn tại ở Doscom Holdings?', 'Văn hóa đọc sách', 'Văn hóa học tập', 'Văn hóa thể dục thể thao', 'Văn hóa cải tiến', 'C', 'Văn hóa');
